=Important: Return ONLY valid JSON. Do not include introductory text, markdown backticks, or preamble.

You are a SEO Keyword Strategist for home services businesses.

Analyze the target service request and location provided below. Extract the primary keyword, target persona, and best local positioning angle.

Inputs:
- Core Service: {{ $json.service_name || "Sewer Line Inspection" }}
- Target Location: {{ $json.target_location || "Peoria, AZ" }}

Output JSON format with exact keys:
{
  "keyword": "string - target high-intent keyword",
  "target_persona": "string - primary customer demographic and pain points",
  "recommended_angle": "string - local hook or climate/geographic consideration"
}

parameters.jsCode:
let rawText = $input.first().json.content[0].text;

// Clean markdown code blocks if present
let cleanedText = rawText.replace(/```json\s*/i, '').replace(/\s*```$/i, '').trim();

try {
  const keywordData = JSON.parse(cleanedText);
  return [{ json: keywordData }];
} catch (e) {
  return [{
    json: {
      raw_output: rawText,
      parse_error: e.message
    }
  }];
}

// Extract raw text output from Claude
const rawText = $input.first().json.content[0].text;

// Clean code block wrappers (e.g. ```json ... ```)
let cleanedText = rawText.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/i, '').trim();

try {
  // Parse into clean JSON object
  const contentData = JSON.parse(cleanedText);
  return [{ json: contentData }];
} catch (e) {
  // Safe fallback if JSON formatting has an issue
  return [{ 
    json: { 
      raw_output: rawText,
      parse_error: e.message 
    } 
  }];
}

// Ingestion Normalization Node (Fail-Safe)
const items = $input.all();
const rawData = (items.length > 0 && items[0].json) ? (items[0].json.body || items[0].json) : {};

const randomStr = Math.random().toString(36).substring(2, 7);
const eventId = rawData.event_id || ('evt_' + Date.now() + '_' + randomStr);

const normalizedPayload = {
  event_id: eventId,
  timestamp: new Date().toISOString(),
  source: String(rawData.source || 'webhook_inbound').toLowerCase().trim(),
  payload_type: String(rawData.payload_type || 'content_generation').toLowerCase().trim(),
  data: {
    title: rawData.title ? String(rawData.title).trim() : 'Default Campaign Title',
    target_channel: rawData.target_channel ? String(rawData.target_channel).toLowerCase().trim() : 'webflow',
    meta_description: rawData.meta_description ? String(rawData.meta_description).trim() : '',
    raw_content: rawData.content || rawData.body || ''
  }
};

return [{ json: normalizedPayload }];

// DLQ Payload Formatting Node
const items = $input.all();
const rawData = items[0]?.json || {};

const dlqRecord = {
  quarantine_id: 'dlq_' + Date.now() + '_' + Math.random().toString(36).substring(2, 7),
  original_event_id: rawData.event_id || 'UNKNOWN',
  failed_at: new Date().toISOString(),
  error_details: {
    failed_schema_path: "root.data.validation",
    validation_message: "Missing required fields: title or target_channel"
  },
  raw_payload: rawData,
  status: "QUARANTINED"
};

return [{ json: dlqRecord }];
